input.command:
$root = "g:\0.CMS-MAIN-ALL\check-test\StudentManager"
$folders = @{}
Get-ChildItem -Path $root -Recurse -File | Where-Object { $_.FullName -notmatch '\\obj\\|\\bin\\' } | ForEach-Object {
  $rel = $_.FullName.Substring($root.Length + 1)
  $parts = $rel -split '\\'
  if ($parts.Count -eq 1) {
    if (-not $folders.ContainsKey('.')) { $folders['.'] = @() }
    $folders['.'] += $parts[0]
  } else {
    $folder = $parts[0]
    if (-not $folders.ContainsKey($folder)) { $folders[$folder] = @() }
    $folders[$folder] += ($parts[1..($parts.Count-1)] -join '\')
  }
}
$out = @()
foreach ($key in ($folders.Keys | Sort-Object)) {
  $out += "=== $key ==="
  foreach ($f in ($folders[$key] | Sort-Object)) { $out += $f }
}
$out | Out-File -FilePath "g:\0.CMS-MAIN-ALL\check-test\StudentManager-structure.txt" -Encoding UTF8
Write-Output "Total folders: $($folders.Keys.Count)"
Write-Output "Total files: $(($folders.Values | ForEach-Object { $_.Count } | Measure-Object -Sum).Sum)"
